WITH sales_with_dates AS ( SELECT cc.cc_call_center_sk, cc.cc_name, d_sold.d_year, d_sold.d_month_seq, cs.cs_net_profit, d_open.d_date AS open_date, d_close.d_date AS close_date FROM catalog_sales cs JOIN call_center cc ON cs.cs_call_center_sk = cc.cc_call_center_sk JOIN date_dim d_sold ON cs.cs_sold_date_sk = d_sold.d_date_sk LEFT JOIN date_dim d_open ON cc.cc_open_date_sk = d_open.d_date_sk LEFT JOIN date_dim d_close ON cc.cc_closed_date_sk = d_close.d_date_sk WHERE cs.cs_quantity > 0 ) SELECT cc_call_center_sk AS call_center_sk, cc_name AS call_center_name, d_year AS year, d_month_seq AS month_seq, SUM(cs_net_profit) AS total_profit, COUNT(*) AS sales_cnt, CASE WHEN SUM(cs_net_profit) > 50000 THEN 'High' WHEN SUM(cs_net_profit) > 20000 THEN 'Medium' ELSE 'Low' END AS profit_category, ROW_NUMBER() OVER (PARTITION BY d_year ORDER BY SUM(cs_net_profit) DESC) AS yearly_rank FROM sales_with_dates GROUP BY cc_call_center_sk, cc_name, d_year, d_month_seq HAVING SUM(cs_net_profit) IS NOT NULL ORDER BY year DESC, month_seq ASC, yearly_rank
